import{_ as e}from"./chunks/home.pc.en.BIVUBvtu.js";import{_ as o}from"./chunks/hub.pc.en.Cb61JjFk.js";import{_ as a,o as n,c as r,a5 as s}from"./chunks/framework.BYXPg_yw.js";const y=JSON.parse('{"title":"RBQ App","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/introduction.md","filePath":"manual/gui/introduction.md","lastUpdated":1792759058000}'),d={name:"manual/gui/introduction.md"};function i(h,t,l,c,p,g){return n(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="rbq-app" tabindex="-1">RBQ App <a class="header-anchor" href="#rbq-app" aria-label="Permalink to &quot;RBQ App&quot;">​</a></h1><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads {#downloads}&quot;">​</a></h2><p>Get the nightly RBQ app from the <strong><a href="/RBQ/nightly/manual/downloads/">Downloads</a></strong> page — <strong>RBQ Nightly</strong> on Google Play for Android, the <strong>TestFlight</strong> beta for iPhone and iPad, and the nightly AppImage for Linux desktop and Steam Deck.</p><h2 id="what-the-app-is" tabindex="-1">What the app is <a class="header-anchor" href="#what-the-app-is" aria-label="Permalink to &quot;What the app is&quot;">​</a></h2><p>The <strong>RBQ app</strong> is the operator application for the RBQ quadruped. Once connected to the robot you can change its posture (sit, stand, walk, stairs and more), drive it with on-screen or physical joysticks, watch the robot&#39;s cameras or a 3D view, and check battery, connection and system status.</p><p>One app runs on every supported device:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Package</th><th>Notes</th></tr></thead><tbody><tr><td>Android tablet / phone</td><td>APK</td><td>Touch joysticks; a Bluetooth/USB gamepad can be used instead</td></tr><tr><td>iOS (iPad / iPhone)</td><td>App Store / TestFlight build</td><td>MFi gamepads are supported</td></tr><tr><td>Linux desktop</td><td>AppImage</td><td>Keyboard, mouse and gamepad input</td></tr><tr><td>Steam Deck</td><td>AppImage (Gaming Mode)</td><td>Built-in controller is used as the gamepad</td></tr></tbody></table><p><img src="'+e+'" alt="Control home"></p><h2 id="the-main-screens" tabindex="-1">The main screens <a class="header-anchor" href="#the-main-screens" aria-label="Permalink to &quot;The main screens&quot;">​</a></h2><p><img src="'+o+'" alt="The hub"></p><p>The app opens on the <strong>Hub</strong>. Its header shows the selected robot&#39;s name and connection state on the left — tap the name to open the robot list. At the top right sit the profile button and the same group as the control screen&#39;s top bar: the warning count, the <strong>Robot</strong> battery, your device battery and the red <code>E-STOP</code> button, which stays dimmed until a robot is connected.</p><p>Every other screen carries the same header with the <strong>logo</strong> and a <strong>Control</strong> button at the top left: the logo opens a menu of the main screens, the hub included, and <code>Control</code> goes straight to the control screen. The right side of the header stays the same on every screen, so <code>E-STOP</code> is always in the same place.</p><table tabindex="0"><thead><tr><th>Screen</th><th>Reach it with</th><th>What it is for</th></tr></thead><tbody><tr><td><strong>Control</strong></td><td><code>Control</code> button on the hub</td><td>Live camera / 3D viewport, motion buttons, joysticks, drive settings — see <a href="/RBQ/nightly/manual/gui/control-home.html">Control home</a>. Opens once a robot is connected or the sim is running</td></tr><tr><td><strong>Dashboard</strong></td><td><code>Dashboard</code> tile</td><td>Monitoring cards: system, joints and posture, configuration</td></tr><tr><td><strong>Settings</strong></td><td><code>Settings</code> tile</td><td>Payload setup, gamepad, app settings — see <a href="/RBQ/nightly/manual/gui/settings.html">Settings</a>. The robot tabs are locked while <a href="/RBQ/nightly/manual/gui/emergency.html#spectating">spectating</a></td></tr><tr><td><strong>Maintenance</strong></td><td><code>Maintenance</code> tile</td><td>Power / System, calibration, robot check, PTZ check (robots with a PTZ), firmware and software update; more sections in developer mode — see <a href="/RBQ/nightly/manual/gui/maintenance.html">Maintenance</a>. A dot on the tile means a finished PTZ check result has not been viewed yet. While <a href="/RBQ/nightly/manual/gui/emergency.html#spectating">spectating</a> it shows only remote check</td></tr><tr><td><strong>Logs</strong></td><td><code>Logs</code> tile</td><td>Real-time robot log, system log and black-box playback — see <a href="/RBQ/nightly/manual/gui/logs.html">Logs</a></td></tr><tr><td><strong>Media</strong></td><td><code>Media</code> tile</td><td>Photos, recordings, black-box clips and voice recordings kept on the robot, and sounds to play through it. Opens once a robot is connected</td></tr></tbody></table><p>The <code>Guide</code> tile opens this manual. Robots are connected and added from the robot list — see <a href="/RBQ/nightly/manual/gui/connection.html">Connection</a>.</p><p>The control screen&#39;s top bar comes in two groups. On the left: the <strong>logo</strong>, the status light (tap it for <strong>Overall system status</strong>), the current gait and the signal strength — plus a <code>SLAM</code> chip while an external program is driving. On the right: the warning count, the <strong>Robot</strong> battery, your device battery and the red <code>E-STOP</code> button. On a Steam Deck or a PC, the <code>X</code> next to it closes the app — the robot keeps running.</p><p>Tap the <strong>Robot</strong> battery for its details: charge level, voltage and — on CAN-FD robots, while charging — roughly how long it takes to reach 80%. Above 80% charging slows down by an amount that depends on the charger, so the app gives only an upper bound for the rest. It also warns when a charger is connected but no current flows, or when only one battery pack is detected.</p><h2 id="developer-mode" tabindex="-1">Developer mode <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;Developer mode&quot;">​</a></h2><p>The app runs at the <strong>operator tier</strong> by default, and every screen described in this manual is available there. <strong>Developer mode</strong> unlocks additional items intended for customer developers and integrators — extra motions, the developer sections of <strong>Maintenance</strong>, camera calibration and the external-control toggle on the control home, and a few advanced fields in Settings.</p><p>To enable it, open the profile menu (the round button at the top right), turn on the <strong>Developer mode</strong> toggle and enter the password. The password is issued by Rainbow Robotics and is not printed in this manual.</p><p><strong>What each screen gains, how to turn it on and off, and which actions to be careful with are all collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html">Developer mode</a>.</strong></p>',20)])])}const f=a(d,[["render",i]]);export{y as __pageData,f as default};
